def is_in_trie(root, word):
    node = root
    for ch in word:
        if ch not in node.children:
            return False
        node = node.children[ch]
    return True

def find_smallest_missing(root, prefix):
    """Find smallest string >= prefix that is NOT in the trie"""
    # Try appending empty, then 1, 2, etc.
    if not is_in_trie(root, prefix):
        return prefix

    for suffix_num in range(1, 10**6):
        suffix = str(suffix_num)
        candidate = prefix + suffix
        if not is_in_trie(root, candidate):
            return candidate

    return prefix + "1"

def suggest_password(root, request):
    """Suggest the lexicographically smallest password >= request not in trie"""
    node = root
    prefix_len = len(request)

    # Check if request is already in the trie
    if is_in_trie(root, request):
        # Find smallest string > request
